function bayesBinary(pBgivenA, pBgivenNotA, pA){
  var pNotA=1-pA;
  var pB=pBgivenA*pA + pBgivenNotA*pNotA;
  if(pB<=0) return NaN;
  return pBgivenA*pA/pB;
}
function bayes(pBgivenA, pA, pB){ if(pB<=0) return NaN; return pBgivenA*pA/pB; }
var EXPORTS={bayesBinary:bayesBinary,bayes:bayes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BayesForgePure = EXPORTS; }
